<?php
declare(strict_types=1);
function h(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$ok = false; $message = ''; $size = null; $digest = null;
if ($_SERVER['REQUEST_METHOD'] !== 'POST') { http_response_code(405); $message = 'Este formulario solo acepta envíos desde la mesa de entrada.'; }
elseif (!isset($_FILES['sample']) || !is_array($_FILES['sample'])) { http_response_code(400); $message = 'No recibimos el documento. Revisa el tamaño permitido e inténtalo de nuevo.'; }
elseif (is_array($_FILES['sample']['error'] ?? null) || ($_FILES['sample']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) { http_response_code(400); $message = 'El documento no pudo procesarse. Código de carga: ' . (string) ($_FILES['sample']['error'] ?? UPLOAD_ERR_NO_FILE); }
else { $tmp = $_FILES['sample']['tmp_name'] ?? ''; if (!is_string($tmp) || !is_uploaded_file($tmp)) { http_response_code(400); $message = 'No se pudo verificar el documento recibido.'; } else { $result = hash_file('sha256', $tmp); if ($result === false) { http_response_code(500); $message = 'No se pudo generar el comprobante.'; } else { $ok = true; $message = 'Documento recibido para revisión inicial'; $size = filesize($tmp); $digest = $result; } } }
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Comprobante | Archivo Costero</title><link rel="stylesheet" href="/style.css"></head>
<body><div class="topline"><div class="wrap">Archivo Costero <span>Portal de servicios digitales</span></div></div><header class="site-header wrap"><a class="brand" href="/"><span class="brand-mark">AC</span><span>Archivo<br><strong>Costero</strong></span></a></header>
<main class="receipt-wrap wrap"><p class="eyebrow">Mesa de entrada / Comprobante</p><section class="receipt"><span class="receipt-icon" aria-hidden="true"><?= $ok ? '✓' : '!' ?></span><h1><?= h($message) ?></h1><?php if ($ok): ?><p>La revisión inicial terminó. Conserva estos datos para identificar el archivo que enviaste.</p><dl class="receipt-facts"><div><dt>Tamaño</dt><dd><?= h((string) $size) ?> bytes</dd></div><div><dt>Huella SHA-256</dt><dd><code><?= h((string) $digest) ?></code></dd></div></dl><p class="field-help">Este comprobante es informativo. El archivo temporal se elimina al finalizar la solicitud.</p><?php endif; ?><a class="button" href="/">Volver al inicio <span aria-hidden="true">→</span></a></section></main>
<footer><div class="wrap footer-bottom">© 2026 Archivo Costero · Portal de demostración</div></footer></body></html>
